import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';

export async function runMotionStreamSmoke(page){
 const viewport=page.viewport(),previous=await page.evaluate(()=>({project:JSON.stringify(project),curPage,curSec,curEl,curPane,selection,secFocus,mode:NAGWEB_STORY_EDITOR.canvasMode(),timeline:NAGWEB_STORY_TIMELINE_UI.state()})),dir=await fs.mkdtemp(path.join(os.tmpdir(),'nagweb-stream-')),file=path.join(dir,'Propia.svg');await fs.writeFile(file,'<svg xmlns="http://www.w3.org/2000/svg" width="300" height="180"><rect width="300" height="180" fill="#f0aa88"/><circle cx="150" cy="90" r="55" fill="#252932"/></svg>');await fs.mkdir('/tmp/nagweb-motion-visuals',{recursive:true});
 async function ready(count=12){await page.waitForFunction(count=>{const f=document.querySelector('.nw-motion-dialog iframe'),d=f?.contentDocument;return d?.querySelectorAll('.nw-stream-card').length===count&&Array.from(d.querySelectorAll('[data-nw-stream-slot] img')).every(n=>n.complete&&n.naturalWidth>0)&&Array.from(d.querySelectorAll('.nw-stream-card')).every(n=>n.width>10);},{timeout:15000},count);}
 let revision=0;async function change(selector,value){const mark='before-'+(++revision);await page.$eval(selector,(n,{v,mark})=>{document.querySelector('.nw-motion-dialog iframe').contentDocument.body.dataset.streamBefore=mark;if(n.type==='checkbox')n.checked=v;else n.value=v;n.dispatchEvent(new Event('change',{bubbles:true}));},{v:value,mark});await page.waitForFunction(mark=>{const f=document.querySelector('.nw-motion-dialog iframe'),d=f?.contentDocument;return d?.body&&d.body.dataset.streamBefore!==mark&&d.querySelector('.nw-stream-card')?.width>10&&f.contentWindow.__NAG_SCROLL_DIRECTOR?.[d.querySelector('.sc').dataset.id];},{timeout:10000},mark);}
 async function pose(p,selector='.nw-motion-dialog iframe',gid){return page.evaluate(({p,selector,gid})=>{const f=document.querySelector(selector),d=f.contentDocument,rt=f.contentWindow.__NAG_SCROLL_DIRECTOR[gid||d.querySelector('.sc').dataset.id];rt.set(p);return Array.from(d.querySelectorAll('[data-nw-stream-slot]'),n=>({id:n.dataset.id,left:n.style.left,top:n.style.top,width:n.style.width,height:n.style.height,depth:n.dataset.nwStreamDepth,phase:n.dataset.nwStreamPhase,z:n.style.zIndex,alpha:n.querySelector('canvas').style.opacity}));},{p,selector,gid});}
 async function exported(gid){await page.evaluate(()=>{document.querySelector('#stream-export')?.remove();const f=document.createElement('iframe');f.id='stream-export';f.style.cssText='width:1280px;height:720px';f.srcdoc=generateSite(flattenPage(page()),false,false,false);document.body.append(f);});await page.waitForFunction(gid=>{const f=document.querySelector('#stream-export');return f?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[gid]&&f.contentDocument.querySelectorAll('.nw-stream-card').length>=4;},{},gid);}
 try{
  await page.evaluate(()=>{const outside=mkEl('label',{name:'Exterior',text:'Fuera del anillo'});project.pages[0].sections=[mkSection({layout:'free',sdEnabled:false,elements:[outside]})];curPage=0;curSec=0;curEl=0;selection=[outside.id];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});const before=await page.evaluate(()=>({project:JSON.stringify(project),stored:localStorage.getItem(STORE_KEY),outside:sec().elements[0],assets:project.assets.images.length}));
  await page.click('.tb-left [data-motion-open]');await page.click('[data-motion-template="showcase-stream"]');await ready();assert.equal(await page.$eval('[data-motion-stream-count]',n=>n.value),'12');assert.equal(await page.$eval('[data-motion-config="duration"]',n=>n.value),'16');const zero=await pose(0),end=await pose(1);assert.deepEqual(zero.map(({phase,...n})=>n),end.map(({phase,...n})=>n),'A full loop returns to the same pixel bounds and order');assert.notDeepEqual(await pose(.25),zero);assert.ok(zero.some(n=>+n.alpha<.5));assert.equal(new Set(zero.map(n=>n.z)).size,12);
  const f=await (await page.$('.nw-motion-dialog iframe')).contentFrame(),front=zero.reduce((a,b)=>+a.depth>+b.depth?a:b);await pose(0);await (await f.$('[data-id="'+front.id+'"]')).click();assert.equal(await page.$eval('[data-motion-element-name]',n=>n.value),'Imagen 4');assert.equal(await page.$eval('[data-motion-width]',n=>n.closest('.crow').hidden),true,'Slot selection edits content, while the template owns its geometry');assert.equal(await page.$eval('.nw-motion-dialog iframe',f=>f.contentDocument.querySelector('[data-motion-resize]').hidden),true);
  const index=await page.$eval('[data-motion-content-panel] .crow:not([hidden]) [data-motion-upload]',n=>n.dataset.motionUpload);await (await page.$('[data-motion-upload="'+index+'"]')).uploadFile(file);await page.waitForFunction(id=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('[data-id="'+id+'"] img')?.naturalWidth===300,{},front.id);await ready();
  await change('[data-motion-stream-count]','4');await ready(4);await page.click('[data-motion-library-tab="elements"]');assert.equal(await page.$eval('[data-motion-element-remove]',n=>n.disabled),true);await change('[data-motion-stream-count]','12');await ready();await page.waitForFunction(id=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('[data-id="'+id+'"] img')?.naturalWidth===300,{},front.id);
  const old=await pose(.3);await change('[data-motion-stream="ringTilt"]','5');await change('[data-motion-stream="ringOpening"]','70');await ready();assert.notDeepEqual(await pose(.3),old);await change('[data-motion-stream="backgroundType"]','gradient');await change('[data-motion-stream="shadow"]',true);await ready();assert.equal(await page.$eval('[data-stream-background="gradient"]',n=>n.hidden),false);await (await page.$('.nw-motion-dialog')).screenshot({path:'/tmp/nagweb-motion-visuals/stream-desktop.png'});
  await change('[data-motion-stream="backgroundType"]','image');await (await page.$('[data-motion-stream-background-upload]')).uploadFile(file);await page.waitForFunction(()=>!document.querySelector('[data-motion-stream-background-open]').disabled&&document.querySelector('[data-motion-stream="backgroundId"]').value);await ready();assert.equal((await page.$$('[data-motion-layer]')).length,12,'Background upload does not create another card');
  await change('[data-motion-config="source"]','scroll');await change('[data-motion-stream="turns"]','3');await change('[data-motion-stream="start"]','20');await change('[data-motion-stream="end"]','80');await change('[data-motion-stream="scrollLength"]','420');await ready();assert.equal(await page.$eval('[data-stream-time]',n=>n.hidden),true);assert.equal((await pose(.1))[0].phase,'0.000000');assert.equal((await pose(.5))[0].phase,'1.500000');assert.equal((await pose(.9))[0].phase,'3.000000');assert.deepEqual((await pose(.1)).map(({phase,...x})=>x),(await pose(.9)).map(({phase,...x})=>x));
  assert.equal(await page.evaluate(()=>JSON.stringify(project)),before.project);assert.equal(await page.evaluate(()=>localStorage.getItem(STORE_KEY)),before.stored);assert.equal(await page.evaluate(()=>history.length),0);
  await page.click('[data-motion-library-tab="library"]');await page.$eval('[data-motion-library-name]',n=>n.value='Mi anillo');await page.click('[data-motion-library-save]');const saved=await page.evaluate(()=>project.nwMotionLibrary.at(-1));assert.equal(saved.config.stream.turns,3);assert.equal(saved.assets.length,8,'Six demo resources, replacement and background are included');const prepared=await page.evaluate(()=>JSON.stringify(project));
  await page.click('[data-motion-insert-group]');const inserted=await page.evaluate(()=>{const g=sec().elements.find(e=>e.nwMotionInstance);return {project:JSON.stringify(project),gid:g.id,config:g.nwMotionInstance,members:sec().elements.filter(e=>e.parent===g.id),outside:sec().elements[0],length:sec().sdLength,enabled:sec().sdEnabled};});assert.equal(inserted.config.template,'showcase-stream');assert.equal(inserted.members.length,12);assert.equal(inserted.length,420);assert.equal(inserted.enabled,true);assert.deepEqual(inserted.outside,before.outside);
  await exported(inserted.gid);const initial=await pose(.1,'#stream-export',inserted.gid);assert.equal(initial[0].phase,'0.000000');await page.$eval('#stream-export',f=>f.contentWindow.__NAG_SCROLL_DIRECTOR[Object.keys(f.contentWindow.__NAG_SCROLL_DIRECTOR).find(id=>id!==f.contentDocument.querySelector('.sc').dataset.id)].live());await page.$eval('#stream-export',f=>f.contentWindow.scrollTo(0,f.contentDocument.querySelector('.sc').offsetHeight/2-360));await page.waitForFunction(gid=>document.querySelector('#stream-export').contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress()>.2,{},inserted.gid);const progress=await page.$eval('#stream-export',(f,gid)=>f.contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress(),inserted.gid);await page.$eval('#stream-export',f=>f.contentWindow.scrollTo(0,0));await page.waitForFunction(({gid,progress})=>document.querySelector('#stream-export').contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress()<progress,{},{gid:inserted.gid,progress});await page.evaluate(()=>document.querySelector('#stream-export').remove());
  await page.evaluate(id=>NAGWEB_MOTION_LAB.edit(id),inserted.gid);await ready();await change('[data-motion-config="source"]','time');await change('[data-motion-config="duration"]','2');await ready();await page.click('[data-motion-save]');const loop=await page.evaluate(gid=>({project:JSON.stringify(project),enabled:sec().sdEnabled,config:sec().elements.find(e=>e.id===gid).nwMotionInstance,groups:sec().elements.filter(e=>e.nwMotionInstance).length,outside:sec().elements[0]}),inserted.gid);assert.equal(loop.enabled,false,'Returning an automatically directed scene to loop removes the extra scroll route');assert.equal(loop.groups,1);assert.equal(loop.config.loop,true);assert.deepEqual(loop.outside,before.outside);await exported(inserted.gid);const clock=await page.$eval('#stream-export',(f,gid)=>f.contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress(),inserted.gid);await page.waitForFunction(({gid,clock})=>{const f=document.querySelector('#stream-export');return f.contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress()!==clock;},{timeout:3000},{gid:inserted.gid,clock});assert.equal(await page.$eval('#stream-export',f=>!!f.contentDocument.querySelector('.nw-sd-active')),false);await page.evaluate(()=>document.querySelector('#stream-export').remove());await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),inserted.project);await page.evaluate(()=>redo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),loop.project);
  await page.setViewport({width:390,height:844,deviceScaleFactor:1});await page.click('.tb-left [data-motion-open]');await page.click('[data-motion-template="showcase-stream"]');await ready();await change('[data-motion-stream="frameRatio"]','auto');await ready();await (await page.$('.nw-motion-dialog')).screenshot({path:'/tmp/nagweb-motion-visuals/stream-mobile.png'});const mobile=await page.$eval('.nw-motion-dialog iframe',f=>{const h=f.contentDocument.querySelector('[data-nw-stream-slot]').offsetParent,w=h.clientWidth,height=h.clientHeight;return Array.from(f.contentDocument.querySelectorAll('[data-nw-stream-slot]'),n=>({x:parseFloat(n.style.left),y:parseFloat(n.style.top),w:parseFloat(n.style.width),h:parseFloat(n.style.height)})).every(n=>n.x>=0&&n.y>=0&&n.x+n.w<=w&&n.y+n.h<=height);});assert.equal(mobile,true);await page.emulateMediaFeatures([{name:'prefers-reduced-motion',value:'reduce'}]);const reduced=await pose(.1);assert.deepEqual(await pose(.9),reduced,'Reduced motion keeps a still ring');await page.emulateMediaFeatures([]);await page.click('[data-motion-close]');await page.setViewport(viewport);assert.equal(await page.evaluate(()=>JSON.stringify(project)),loop.project);
  // A new scene contains the same editable group, so it can reopen in Motion Lab.
  await page.click('.tb-left [data-motion-open]');await page.click('[data-motion-template="showcase-stream"]');await ready();await page.click('[data-motion-insert]');const newGroup=await page.evaluate(()=>({id:sec().nwMotionSceneGroup,groups:sec().elements.filter(e=>e.nwMotionInstance).length}));assert.equal(newGroup.groups,1);assert.ok(newGroup.id);await page.evaluate(id=>NAGWEB_MOTION_LAB.edit(id),newGroup.id);await ready();await page.click('[data-motion-close]');
  console.log('Showcase Stream: curvas renderizadas/ciclo/capas, selección y archivos propios, controles/cantidad con recuperación, fondo con recursos, scroll de tres vueltas/inicio/fin/recorrido y retroceso real, loop independiente, Biblioteca/instancia/historial, escena reeditable, móvil y movimiento reducido OK');
 }catch(error){await page.screenshot({path:'/tmp/nagweb-motion-visuals/stream-failure.png'}).catch(()=>{});throw error;
 }finally{await page.emulateMediaFeatures([]);await page.setViewport(viewport);await page.evaluate(p=>{document.querySelector('.nw-motion-dialog').close();document.querySelector('#stream-export')?.remove();clearTimeout(previewTimer);project=JSON.parse(p.project);curPage=p.curPage;curSec=p.curSec;curEl=p.curEl;curPane=p.curPane;selection=p.selection;secFocus=p.secFocus;history=[];future=[];NAGWEB_STORY_EDITOR.setCanvasMode(p.mode);NAGWEB_STORY_TIMELINE_UI.setState(p.timeline);saveProject();renderScenes();renderPane();renderPreview();},previous);await fs.rm(dir,{recursive:true,force:true});}
}
